/** Calculate rounded GST once using integer paise; prices are tax-exclusive. */
export function totals(parts: Part[], laborPaise: number, gstBasisPoints: number) {
  const subtotalPaise = parts.reduce((sum, part) => sum + part.quantity * part.pricePaise, laborPaise);
  const taxPaise = Math.round(subtotalPaise * gstBasisPoints / 10000);
  const totalPaise = subtotalPaise + taxPaise;
  if (!Number.isSafeInteger(totalPaise) || totalPaise > 1_000_000_000) throw new Error('Invoice exceeds supported limit');
  return { subtotalPaise, taxPaise, totalPaise };
}

/** Format integer paise as Indian rupees for display only. */
export function rupees(paise: number) {
  return `INR ${(paise / 100).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

/** Use Indian garage calendar dates regardless of the server's UTC timezone. */
export function garageDate(value = new Date()) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(value);
  return `${parts.find(v => v.type === 'year')!.value}-${parts.find(v => v.type === 'month')!.value}-${parts.find(v => v.type === 'day')!.value}`;
}
